' fill='#15803d'>3. İçerik</text><text x='390' y='100' text-anchor='middle' font-size='11' fill='#334155'>Kendi okulunun</text><text x='390' y='118' text-anchor='middle' font-size='11' fill='#334155'>bilgileriyle yaz</text><text x='463' y='108' font-size='16' fill='#64748b'>→</text><rect x='478' y='48' width='132' height='110' rx='12' fill='#faf5ff' stroke='#a855f7' stroke-width='1.5'/><text x='544' y='74' text-anchor='middle' font-size='13' font-weight='bold' fill='#7e22ce'>4. Dönüştür</text><text x='544' y='100' text-anchor='middle' font-size='11' fill='#334155'>medresetî →</text><text x='544' y='118' text-anchor='middle' font-size='11' fill='#334155'>medresetunâ</text><text x='544' y='138' text-anchor='middle' font-size='10' fill='#64748b'>(okulum → okulumuz)</text><text x='617' y='108' font-size='16' fill='#64748b'>→</text><rect x='632' y='48' width='112' height='110' rx='12' fill='#fff7ed' stroke='#f97316' stroke-width='1.5'/><text x='688' y='74' text-anchor='middle' font-size='13' font-weight='bold' fill='#c2410c'>5. Paylaş</text><text x='688' y='100' text-anchor='middle' font-size='11' fill='#334155'>Akran geri</text><text x='688' y='118' text-anchor='middle' font-size='11' fill='#334155'>bildirimi</text><rect x='16' y='176' width='728' height='62' rx='12' fill='#1e3a8a'/><text x='380' y='202' text-anchor='middle' font-size='14' font-weight='bold' fill='#ffffff'>Broşür sloganı: Rutbetü'l-ilmi a'le'r-ruteb</text><text x='380' y='224' text-anchor='middle' font-size='12' fill='#dbeafe'>İlmin derecesi, derecelerin en yücesidir.</text><rect x='16' y='254' width='356' height='60' rx='12' fill='#dcfce7' stroke='#22c55e' stroke-width='1.5'/><text x='194' y='278' text-anchor='middle' font-size='14' font-weight='bold' fill='#14532d'>Mümtâz! (Mükemmel!)</text><text x='194' y='299' text-anchor='middle' font-size='11' fill='#166534'>Arkadaşının güzel broşürünü öv</text><rect x='388' y='254' width='356' height='60' rx='12' fill='#fce7f3' stroke='#ec4899' stroke-width='1.5'/><text x='566' y='278' text-anchor='middle' font-size='14' font-weight='bold' fill='#9d174d'>Tab'an! (Elbette!)</text><text x='566' y='299' text-anchor='middle' font-size='11' fill='#9d174d'>Okuma isteğini memnuniyetle kabul et</text></svg>"}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
